                            .ofNativeType("SERIAL").nullable(false).withColumn("person name").ofSize(255).withColumn(
                                    "age").ofType(ColumnType.INTEGER).execute();
                    assertEquals("[id, person name, age]", Arrays.toString(table.getColumnNames()));
