            cache.edit(key);
            fail("Exepcting an IllegalArgumentException as the key was invalid.");
        } catch (IllegalArgumentException iae) {
            assertEquals("keys must match regex [a-z0-9_]{1,64}: \"" + key + "\"", iae.getMessage());
        }
        try {
            key = "has_CR\r";
            cache.edit(key);
            fail("Exepcting an IllegalArgumentException as the key was invalid.");
        } catch (IllegalArgumentException iae) {
            assertEquals("keys must match regex [a-z0-9_]{1,64}: \"" + key + "\"", iae.getMessage());
        }
        try {
            key = "has_LF\n";
            cache.edit(key);
            fail("Exepcting an IllegalArgumentException as the key was invalid.");
