	                               .containsOnly(tuple("Frodo", 33, HOBBIT, "Frodo", 33, HOBBIT),
	                                             tuple("Sam", 38, HOBBIT, "Sam", 38, HOBBIT),
	                                             tuple("Gandalf", 2020, MAIA, "Gandalf", 2020, MAIA),
