                .substateOf(State.C)
                .permit(Trigger.X, State.A);

        sm.configure(State.C)
                .permit(Trigger.X, State.B);

        List<Trigger> permitted = sm.getPermittedTriggers();
        assertEquals(1, permitted.size());
        assertEquals(Trigger.X, permitted.get(0));
    }

