public class DAOFRCreditNoteImpl extends AbstractDAOFRGenericInvoiceImpl<FRCreditNoteEntity, JPAFRCreditNoteEntity>
        implements DAOFRCreditNote {

    @Inject
    public DAOFRCreditNoteImpl(Provider<EntityManager> emProvider) {
        super(emProvider);
