    /**
     * Hanging items broken by a player fall under the HangingBreakByEntityEvent
     * events. This is merely here to capture cause = physics for when they detach
     * from a block.
     *
     * @param event HangingBreakEvent
     */
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onHangingBreakEvent(final HangingBreakEvent event) {

        // Ignore other causes. Entity cause already handled.
        if (!event.getCause().equals(RemoveCause.PHYSICS)) {
            return;
        }

        if (!Prism.getIgnore().event("hangingitem-break", event.getEntity().getWorld())) {
            return;
        }

        final Hanging e = event.getEntity();

        // Check for planned hanging item breaks
        final String coord_key = e.getLocation().getBlockX() + ":" + e.getLocation().getBlockY() + ":"
                + e.getLocation().getBlockZ();

        String value = plugin.preplannedBlockFalls.remove(coord_key);

        if (value == null) {
            value = "unknown";
        }

        Player player = null;
        try {
            player = Bukkit.getPlayer(UUID.fromString(value));
        } catch (Exception ignored) {
            //ignored.
        }

        // Track the hanging item break
        if (player != null) {
            RecordingQueue.addToQueue(ActionFactory.createHangingItem("hangingitem-break", e, player));
        } else {
            RecordingQueue.addToQueue(ActionFactory.createHangingItem("hangingitem-break", e, value));
        }

        plugin.preplannedBlockFalls.remove(coord_key);

        if (!Prism.getIgnore().event("item-remove", event.getEntity().getWorld())) {
            return;
        }

        // If an item frame, track it's contents
        if (e instanceof ItemFrame) {
            final ItemFrame frame = (ItemFrame) e;
            if (!checkNotNullorAir(frame.getItem())) {
                if (player != null) {
                    RecordingQueue.addToQueue(ActionFactory.createItemStack("item-remove", frame.getItem(),
                            frame.getItem().getAmount(), -1, null, e.getLocation(), player));
                } else {
                    RecordingQueue.addToQueue(ActionFactory.createItemStack("item-remove", frame.getItem(),
                            frame.getItem().getAmount(), -1, null, e.getLocation(), value));
                }
            }
        }
    }

    /**
     * HangingBreakByEntityEvent.
     * @param event HangingBreakByEntityEvent
     */
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onHangingBreakByEntityEvent(final HangingBreakByEntityEvent event) {

        final Entity entity = event.getEntity();
        final Entity remover = event.getRemover();
        Player player = null;
        if (remover instanceof Player) {
            player = (Player) remover;
        }
        // Cancel the event if a wand is in use
        if (player != null && WandUtils.playerUsesWandOnClick(player, event.getEntity().getLocation())) {
            event.setCancelled(true);
            return;
        }

        if (!Prism.getIgnore().event("hangingitem-break", event.getEntity().getWorld())) {
            return;
        }
        String breakingName = (remover == null) ? "NULL" : remover.getType().name().toLowerCase();
        if (player != null) {
            RecordingQueue.addToQueue(ActionFactory.createHangingItem("hangingitem-break", event.getEntity(), player));
        } else {
            RecordingQueue
                    .addToQueue(ActionFactory.createHangingItem("hangingitem-break", event.getEntity(), breakingName));
        }
        if (!Prism.getIgnore().event("item-remove", event.getEntity().getWorld())) {
            return;
        }
        // If an item frame, track it's contents
        if (event.getEntity() instanceof ItemFrame) {
            final ItemFrame frame = (ItemFrame) event.getEntity();
            if (!checkNotNullorAir(frame.getItem())) {
                RecordingQueue.addToQueue(ActionFactory.createItemStack("item-remove", frame.getItem(),
                        frame.getItem().getAmount(), -1, null, entity.getLocation(), breakingName));
            }
        }
    }

    /**
     * EntityChangeBlockEvent.
     * @param event EntityChangeBlockEvent
     */

    // TODO: This is a mess. Please, for the love of god, revisit and fix.
    @Deprecated
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onEntityChangeBlock(final EntityChangeBlockEvent event) {
        final String entity = MiscUtils.getEntityName(event.getEntity());

        // Technically I think that I really should name it "entity-eat" for
        // better consistency and
        // in case other mobs ever are made to eat. But that's not as fun
        Material to = event.getTo();
        Material from = event.getBlock().getType();
        if (from == Material.GRASS && to == Material.DIRT) {
            if (event.getEntityType() != EntityType.SHEEP) {
                return;
            }
            if (!Prism.getIgnore().event("sheep-eat", event.getBlock())) {
                return;
            }
            RecordingQueue.addToQueue(ActionFactory.createBlock("sheep-eat", event.getBlock(), entity));
        } else if (to == Material.AIR ^ from == Material.AIR && event.getEntity() instanceof Enderman) {
            if (from == Material.AIR) {
                if (!Prism.getIgnore().event("enderman-place", event.getBlock())) {
                    return;
                }
                BlockState state = event.getBlock().getState();
                state.setType(to);
                RecordingQueue.addToQueue(ActionFactory.createBlock("enderman-place", state, entity));
            } else {
                if (!Prism.getIgnore().event("enderman-pickup", event.getBlock())) {
                    return;
                }

                BlockState state = event.getBlock().getState();
                state.setBlockData(event.getBlockData());
                RecordingQueue.addToQueue(ActionFactory.createBlock("enderman-pickup", state, entity));
            }
        } else if (to == Material.AIR && event.getEntity() instanceof Wither) {
            if (!Prism.getIgnore().event("entity-break", event.getBlock())) {
                return;
            }
            RecordingQueue.addToQueue(ActionFactory.createBlock("block-break", event.getBlock(),
                    event.getEntityType().name().toLowerCase()));
        }
    }

    /**
     * EntityBlockFormEvent.
     * @param event EntityBlockFormEvent
     */
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onEntityBlockForm(final EntityBlockFormEvent event) {
        if (!Prism.getIgnore().event("entity-form", event.getBlock())) {
            return;
        }
        final Block block = event.getBlock();
        final Location loc = block.getLocation();
        final BlockState newState = event.getNewState();

        if (event.getEntity() instanceof Player) {
            final Player player = (Player)event.getEntity();
            RecordingQueue.addToQueue(ActionFactory.createBlockChange("entity-form", loc, block.getType(),
                    block.getBlockData(), newState.getType(), newState.getBlockData(), player));
        } else {
            final String entity = event.getEntity().getType().name().toLowerCase();
            RecordingQueue.addToQueue(ActionFactory.createBlockChange("entity-form", loc, block.getType(),
                    block.getBlockData(), newState.getType(), newState.getBlockData(), entity));
        }
    }

    /**
     * EntityExplodeEvent.
     * @param event EntityExplodeEvent
     */
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onEntityExplodeChangeBlock(final EntityExplodeEvent event) {

        if (event.blockList().isEmpty()) {
            return;
        }
        String name;
        String action = "entity-explode";
        if (event.getEntity() != null) {
            if (event.getEntity() instanceof Creeper) {
                if (!Prism.getIgnore().event("creeper-explode", event.getEntity().getWorld())) {
                    return;
                }
                action = "creeper-explode";
                name = "creeper";
            } else if (event.getEntity() instanceof TNTPrimed) {
                if (!Prism.getIgnore().event("tnt-explode", event.getEntity().getWorld())) {
                    return;
                }
                action = "tnt-explode";
                Entity source = ((TNTPrimed) event.getEntity()).getSource();
                name = followTntTrail(source);
            } else if (event.getEntity() instanceof EnderDragon) {
                if (!Prism.getIgnore().event("dragon-eat", event.getEntity().getWorld())) {
                    return;
                }
                action = "dragon-eat";
                name = "enderdragon";
            } else {
                if (!Prism.getIgnore().event("entity-explode", event.getLocation().getWorld())) {
                    return;
                }
                try {
                    name = event.getEntity().getType().name().toLowerCase().replace("_", " ");
                    name = name.length() > 15 ? name.substring(0, 15) : name; // I
                } catch (final NullPointerException e) {
                    name = "unknown";
                }
            }
        } else {
            if (!Prism.getIgnore().event("entity-explode", event.getLocation().getWorld())) {
                return;
            }
            name = "magic";
        }
        contructBlockEvent(action,name,event.blockList());
    }

    private String followTntTrail(Entity initial) {
        int counter = 10000000;

        while (initial != null) {
            if (initial instanceof Player) {
                return initial.getName();
            } else if (initial instanceof TNTPrimed) {
                initial = (((TNTPrimed) initial).getSource());
                if (counter < 0 && initial != null) {
                    Location last = initial.getLocation();
                    plugin.getLogger().warning("TnT chain has exceeded one million, will not continue!");
                    plugin.getLogger().warning("Last Tnt was at " + last.getX() + ", " + last.getY() + ". "
                            + last.getZ() + " in world " + last.getWorld());
                    return "tnt";
                }
                counter--;
            } else {
                return initial.getType().name();
            }
        }

        return "tnt";
    }
}

package me.botsko.prism.utils;

import org.bukkit.Chunk;
import org.bukkit.Material;
import org.bukkit.block.Block;
import org.bukkit.block.data.BlockData;
import org.bukkit.entity.Player;
import org.bukkit.util.Vector;

import java.util.ArrayList;

public class ChunkUtils {

    /**
     * Resets the preview border blocks.
     *
     * @param player Player
     * @param blocks Iterable Block list,
     */
    public static void resetPreviewBoundaryBlocks(Player player, Iterable<Block> blocks) {
        for (Block block : blocks) {
            EntityUtils.sendBlockChange(player, block.getLocation(), block.getBlockData());
        }
    }

    /**
     * Sets a block in preview mode around the border of a chunk.
     *
     * @param player Player
     * @param blocks Iterable Block list,
     */
    public static void setPreviewBoundaryBlocks(Player player, Iterable<Block> blocks, Material m) {
        BlockData blockData = m.createBlockData();
        for (Block block : blocks) {
            EntityUtils.sendBlockChange(player, block.getLocation(), blockData);
        }
    }

    /**
     * Returns the minimum vector for the chunk.
     *
     * @param chunk Chunk
     * @return Vector
     */
    public static Vector getChunkMinVector(Chunk chunk) {
        int blockMinX = chunk.getX() * 16;
        int blockMinZ = chunk.getZ() * 16;
        return new Vector(blockMinX, 0, blockMinZ);
    }

    /**
     * Returns the maximum vector for the chunk.
     *
     * @param chunk Chunk
     * @return Vector
     */
    public static Vector getChunkMaxVector(Chunk chunk) {
        int blockMinX = chunk.getX() * 16;
        int blockMinZ = chunk.getZ() * 16;
        int blockMaxX = blockMinX + 15;
        int blockMaxZ = blockMinZ + 15;
        return new Vector(blockMaxX, chunk.getWorld().getMaxHeight(), blockMaxZ);
    }

    /**
     * Returns an array of boundary blocks at a single Y for the current chunk.
     *
     * @param chunk chunk
     * @param y height
     * @return List of Blocks
     */
    public static ArrayList<Block> getBoundingBlocksAtY(Chunk chunk, int y) {

        int blockMinX = chunk.getX() * 16;
        int blockMinZ = chunk.getZ() * 16;
        int blockMaxX = blockMinX + 15;
        int blockMaxZ = blockMinZ + 15;

        ArrayList<Block> blocks = new ArrayList<>();

        // MinX -> MinZ
        for (int x = blockMinX; x < blockMaxX; x++) {
            blocks.add(chunk.getWorld().getBlockAt(x, y, blockMinZ));
        }
        // MinX -> MaxZ
        for (int x = blockMinX; x < blockMaxX; x++) {
            blocks.add(chunk.getWorld().getBlockAt(x, y, blockMaxZ));
        }
        // MinZ -> MinX
        for (int z = blockMinZ; z < blockMaxZ; z++) {
            blocks.add(chunk.getWorld().getBlockAt(blockMinX, y, z));
        }
        // MinZ -> MaxX
        for (int z = blockMinZ; z < blockMaxZ; z++) {
            blocks.add(chunk.getWorld().getBlockAt(blockMaxX, y, z));
        }

        return blocks;

    }
}

package me.botsko.prism.utils;

import org.bukkit.NamespacedKey;
import org.bukkit.enchantments.Enchantment;
import org.bukkit.inventory.ItemStack;

import java.util.Map;

public class EnchantmentUtils {

    /**
     * Given an enchantment, does the current item have any that conflict.
     *
     * @return bool
     */
    @SuppressWarnings("unused")
    public static boolean hasConflictingEnchanment(ItemStack item, Enchantment ench) {
        Map<Enchantment, Integer> enchantments = item.getEnchantments();
        boolean conflict = false;
        for (Enchantment e : enchantments.keySet()) {
            if (ench.conflictsWith(e)) {
                conflict = true;
            }
        }
        return (enchantments.containsKey(ench) || conflict);
    }

    /**
     * Return the enchantment based on a common name.
     *
     * @param name String
     * @return Enchantment
     */
    @SuppressWarnings("unused")
    public static Enchantment getEnchantmentFromCommonName(String name) {
        switch (name.toLowerCase()) {
            case "aquaaffinity":
                return Enchantment.WATER_WORKER;
            case "bane":
                return Enchantment.DAMAGE_ARTHROPODS;
            case "efficiency":
                return Enchantment.DIG_SPEED;
            case "explosion":
                return Enchantment.PROTECTION_EXPLOSIONS;
            case "fall":
                return Enchantment.PROTECTION_FALL;
            case "fire":
                return Enchantment.PROTECTION_FIRE;
            case "fireaspect":
                return Enchantment.FIRE_ASPECT;
            case "flame":
                return Enchantment.ARROW_FIRE;
            case "fortune":
                return Enchantment.LOOT_BONUS_BLOCKS;
            case "infinity":
                return Enchantment.ARROW_INFINITE;
            case "knockback":
                return Enchantment.KNOCKBACK;
            case "power":
                return Enchantment.ARROW_DAMAGE;
            case "looting":
                return Enchantment.LOOT_BONUS_MOBS;
            case "projectile":
                return Enchantment.PROTECTION_PROJECTILE;
            case "protection":
                return Enchantment.PROTECTION_ENVIRONMENTAL;
            case "punch":
                return Enchantment.ARROW_KNOCKBACK;
            case "respiration":
                return Enchantment.OXYGEN;
            case "sharpness":
                return Enchantment.DAMAGE_ALL;
            case "silktouch":
                return Enchantment.SILK_TOUCH;
            case "smite":
                return Enchantment.DAMAGE_UNDEAD;
            case "unbreaking":
                return Enchantment.DURABILITY;
            default:
                String formattedName = name.replace(' ','_');
                NamespacedKey key = NamespacedKey.minecraft(formattedName);
                return Enchantment.getByKey(key);
        }
    }

    /**
     * Return the common name for an enchantment.
     *
     * @param enchantment Keyed
     * @param level int
     * @return String
     */
    public static String getClientSideEnchantmentName(Enchantment enchantment, int level) {

        String enchantName;

        if (enchantment.equals(Enchantment.ARROW_DAMAGE)) {
            enchantName = "power";
        } else if (enchantment.equals(Enchantment.ARROW_FIRE)) {
            enchantName = "flame";
        } else if (enchantment.equals(Enchantment.ARROW_INFINITE)) {
            enchantName = "infinity";
        } else if (enchantment.equals(Enchantment.ARROW_KNOCKBACK)) {
            enchantName = "punch";
        } else if (enchantment.equals(Enchantment.DAMAGE_ALL)) {
            enchantName = "sharpness";
        } else if (enchantment.equals(Enchantment.DAMAGE_ARTHROPODS)) {
            enchantName = "bane of anthropods";
        } else if (enchantment.equals(Enchantment.DAMAGE_UNDEAD)) {
            enchantName = "damage undead";
        } else if (enchantment.equals(Enchantment.DIG_SPEED)) {
            enchantName = "efficiency";
        } else if (enchantment.equals(Enchantment.DURABILITY)) {
            enchantName = "unbreaking";
        } else if (enchantment.equals(Enchantment.LOOT_BONUS_BLOCKS)) {
            enchantName = "fortune";
        } else if (enchantment.equals(Enchantment.LOOT_BONUS_MOBS)) {
            enchantName = "looting";
        } else if (enchantment.equals(Enchantment.OXYGEN)) {
            enchantName = "respiration";
        } else if (enchantment.equals(Enchantment.PROTECTION_ENVIRONMENTAL)) {
            enchantName = "protection";
        } else if (enchantment.equals(Enchantment.PROTECTION_EXPLOSIONS)) {
            enchantName = "blast protection";
        } else if (enchantment.equals(Enchantment.PROTECTION_FALL)) {
            enchantName = "feather falling";
        } else if (enchantment.equals(Enchantment.PROTECTION_FIRE)) {
            enchantName = "fire protection";
        } else if (enchantment.equals(Enchantment.PROTECTION_PROJECTILE)) {
            enchantName = "projectile protection";
        } else if (enchantment.equals(Enchantment.WATER_WORKER)) {
            enchantName = "aqua affinity";
        } else if (enchantment.equals(Enchantment.VANISHING_CURSE)) {
            enchantName = "vanishing curse";
        } else {
            // can leave as-is: SILK_TOUCH, FIRE_ASPECT, KNOCKBACK, THORNS, LUCK, LURE
            enchantName = enchantment.getKey().getKey().toLowerCase().replace("_", " ");
        }
        switch (level) {
            case 1:
                enchantName += " I";
                break;
            case 2:
                enchantName += " II";
                break;
            case 3:
                enchantName += " III";
                break;
            case 4:
                enchantName += " IV";
                break;
            case 5:
                enchantName += " V";
                break;
            default:
                enchantName += " " + level;
        }
        return enchantName;

    }
}

package me.botsko.prism.utils;

import me.botsko.prism.Prism;
import me.botsko.prism.api.objects.MaterialState;
import me.botsko.prism.database.IdMapQuery;
import me.botsko.prism.database.sql.SqlIdMapQuery;
import me.botsko.prism.utils.block.Utilities;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.block.data.BlockData;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.inventory.ItemStack;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Map.Entry;
import java.util.Set;

public class MaterialAliases {
    private static final int SUBID_WILDCARD = -1;
    private final Map<String, String> matCache = new HashMap<>();
    private final Map<String, String> idCache = new HashMap<>();
    private final Map<Material, Set<IntPair>> allIdsCache = new HashMap<>();

    private final HashMap<String, String> itemAliases = new HashMap<>();

    /**
     * Load the yml file and save config to hashmap.
     */
    public MaterialAliases() {
        FileConfiguration items = null;
        InputStream defConfigStream = this.getClass().getResourceAsStream("/items.yml");
        if (defConfigStream != null) {
            Prism.log("Elixr: Loaded items directory");
            items = YamlConfiguration.loadConfiguration(new InputStreamReader(defConfigStream));
        }


        if (items != null) {

            // Load all item ids/aliases
            ConfigurationSection sec = items.getConfigurationSection("items");
            Map<String, Object> itemAliases = null;

            if (sec != null) {
                itemAliases = sec.getValues(false);
            }
            // Cache the values for easier lookup
            if (itemAliases != null) {
                for (Map.Entry<String, Object> entry : itemAliases.entrySet()) {
                    @SuppressWarnings("unchecked")
                    Iterable<String> aliases = (List<String>) entry.getValue();

                    for (String alias : aliases) {
                        this.itemAliases.put(entry.getKey().toLowerCase(), alias);
                    }
                }
            }

        } else {
            Prism.warn("ERROR: The Item library was unable to load an internal item alias list.");
        }
    }

    public void initAllMaterials() {
        initMaterials(Material.values());
    }

    /**
     * Initialize the library.
     *
     * @param materials Materials ...
     */
    public void initMaterials(Material... materials) {
        Bukkit.getScheduler().runTaskAsynchronously(Prism.getInstance(), () -> {
            SqlIdMapQuery query = new SqlIdMapQuery(Prism.getPrismDataSource());
            for (Material m : materials) {
                String matName = m.name().toLowerCase(Locale.ENGLISH);
                String dataString;

                try {
                    dataString = Utilities.dataString(Bukkit.createBlockData(m));
                } catch (IllegalArgumentException e) {
                    continue;
                }

                query.findIds(m.name().toLowerCase(Locale.ENGLISH), dataString,
                      (i, d) ->
                        storeCache(m, dataString, i, d), () -> {
                        int id = query.mapAutoId(matName, dataString);
                        storeCache(m, dataString, id, 0);
                      });
            }
        });

    }

    private Set<IntPair> getIdsOf(Material material) {
        Set<IntPair> ids = allIdsCache.get(material);
        if (ids != null) {
            return ids;
        }

        IdMapQuery query = new SqlIdMapQuery(Prism.getPrismDataSource());

        query.findAllIds(material.name().toLowerCase(Locale.ENGLISH), list -> allIdsCache.put(
                material, new HashSet<>(list)));
        return allIdsCache.get(material);
    }

    private void storeCache(Material material, String state, int blockId, int blockSubid) {
        String matKey = material.name().toLowerCase(Locale.ENGLISH) + ":" + state;
        String idKey = blockId + ":" + blockSubid;

        matCache.put(idKey, matKey);
        idCache.put(matKey, idKey);

        getIdsOf(material).add(new IntPair(blockId, blockSubid));
    }

    private MaterialState fromCache(int blockId, int blockSubid) {
        String value = matCache.get(blockId + ":" + blockSubid);

        if (value != null) {
            String[] parts = value.split(":", 2);

            return new MaterialState(Material.matchMaterial(parts[0]), parts[1]);
        }

        return null;
    }

    private IntPair fromCache(Material material, String state) {
        String value = idCache.get(material.name().toLowerCase(Locale.ENGLISH) + ":" + state);

        if (value != null) {
            String[] parts = value.split(":", 2);

            return new IntPair(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
        }

        return null;
    }

    /**
     * .
     *
     * @param blockId           int
     * @param blockSubId        logMaterialErrorsint
     * @param logMaterialErrors boolean.
     * @return MaterialState
     */
    public MaterialState idsToMaterial(int blockId, int blockSubId, Boolean logMaterialErrors) {
        MaterialState cachedMaterial = fromCache(blockId, blockSubId);

        if (cachedMaterial != null) {
            return cachedMaterial;
        }

        MaterialState result = new MaterialState();
        SqlIdMapQuery query = new SqlIdMapQuery(Prism.getPrismDataSource());

        query.findMaterial(blockId, blockSubId,
              (material, state) -> {
                  result.material = Material.matchMaterial(material.toUpperCase(Locale.ENGLISH));
                  result.state = state;
                  if (result.material != null) {
                      storeCache(result.material, result.state, blockId, blockSubId);
                  }
              }, () -> {
                  if (logMaterialErrors) {
                      Prism.log("matError: [" + blockId + ", " + blockSubId + "] -> ???");
                  }
              });

        if (result.material == null) {
            return null;
        }

        return result;
    }

    /**
     * Create IntPair.
     *
     * @param material Material
     * @param state    State
     * @return IntPair
     */
    public IntPair materialToIds(Material material, String state) {
        int blockSubId;

        // For tools, where durability doesn't mean a different item (different cached
        // value) but is still important
        int durability = 0;
        try {
            durability = Integer.parseInt(state);
        } catch (NumberFormatException ignored) {
            //ignored
        }

        if (material.getMaxDurability() > 0) {
            blockSubId = 0;
        } else {
            blockSubId = durability;
        }

        IntPair cachedIds = fromCache(material, blockSubId == 0 ? state : String.valueOf(blockSubId));

        if (cachedIds != null) {
            return cachedIds;
        }

        IntPair result = new IntPair(0, 0);
        SqlIdMapQuery query = new SqlIdMapQuery(Prism.getPrismDataSource());
        String materialName = material.name().toLowerCase(Locale.ENGLISH);

        synchronized (this) {
            query.findIds(materialName, state,
                  (queryId, querySubId) -> {
                    result.first = queryId;
                    result.second = querySubId;
                    storeCache(material, state, queryId, querySubId); },
                  () -> {
                    int blockId = query.mapAutoId(materialName, state);
                    result.first = blockId;
                    storeCache(material, state, blockId, 0); });
        }

        if (blockSubId != durability) {
            result.second = durability;
        }
        return result;
    }

    public Set<IntPair> materialToAllIds(Material material) {
        return Collections.unmodifiableSet(getIdsOf(material));
    }

    /**
     * .
     *
     * @param material         Material
     * @param partialBlockData String
     * @return Set of IntPair
     * @throws IllegalArgumentException exception
     */
    public Set<IntPair> partialBlockDataIds(Material material, String partialBlockData)
            throws IllegalArgumentException {
        String fullBlockData = Utilities.dataString(Bukkit.createBlockData(material, partialBlockData));

        String[] parts = fullBlockData.substring(1, fullBlockData.length() - 1).toLowerCase(Locale.ENGLISH).split(",");

        StringBuilder likeString = new StringBuilder("%");

        for (String string : parts) {
            if (partialBlockData.contains(string)) {
                likeString.append(string).append('%');
            }
        }

        String stateLike = likeString.toString();

        IdMapQuery query = new SqlIdMapQuery(Prism.getPrismDataSource());

        Set<IntPair> ids = new HashSet<>();
        query.findAllIdsPartial(material.name().toLowerCase(Locale.ENGLISH), stateLike, ids::addAll);

        return ids;
    }

    /**
     * .
     *
     * @param material Material
     * @param state    String
     * @return IntPair
     */
    @Deprecated
    public IntPair materialToIdsWildcard(Material material, String state) {
        IntPair ids = materialToIds(material, state);

        if (material.getMaxDurability() > 0) {
            ids.second = SUBID_WILDCARD;
        }
        return ids;
    }

    /**
     * Returns the loaded list of item aliases/ids.
     *
     * @return HashMap
     */
    @Deprecated
    public HashMap<String, String> getItemAliases() {
        return itemAliases;
    }

    /**
     * .
     *
     * @param material Material
     * @param data     BlockData
     * @return String
     */
    public String getAlias(Material material, BlockData data) {
        String dataString = Utilities.dataString(data);

        String itemName = null;
        if (!itemAliases.isEmpty()) {
            String key = material.name().toLowerCase() + dataString;
            itemName = itemAliases.get(key);
        }
        if (itemName == null) {
            itemName = material.name().toLowerCase().replace("_", " ");
        }
        return itemName;
    }

    /**
     * Returns the proper name given an item stack.
     *
     * @param i ItemStack
     * @return String
     */
    public String getAlias(ItemStack i) {
        return i.getType().name().toLowerCase().replace("_", " ");
    }

    /**
     * .
     *
     * @param alias String
     * @return ArrayList
     */
    // TODO: Break this in 1.13. Woooo.
    public ArrayList<Material> getMaterialsByAlias(String alias) {
        ArrayList<Material> itemIds = new ArrayList<>();
        if (!itemAliases.isEmpty()) {
            for (Entry<String, String> entry : itemAliases.entrySet()) {
                if (entry.getValue().equals(alias)) {
                    itemIds.add(Material.matchMaterial(entry.getKey()));
                }
            }
        }
        return itemIds;
    }

