import static org.bukkit.Material.TRAPPED_CHEST;
import static org.bukkit.Material.WATER;


public class BlockAction extends GenericAction {

    private BlockActionData actionData;

    /**
     * Set the Block.
     *
     * @param block Block
     */
    public void setBlock(Block block) {
        if (block != null) {
            setBlock(block.getState());
        }
    }

    /**
     * Set the Block State.
     *
     * @param state BlockState.
     */
    public void setBlock(BlockState state) {
        if (state != null) {
            setMaterial(state.getType());
            setBlockData(state.getBlockData());
            createActionData(state);
            setLoc(state.getLocation());
        }
    }

    private void createActionData(BlockState state) {
        switch (state.getType()) {
            case SPAWNER:
                final SpawnerActionData spawnerActionData = new SpawnerActionData();
                final CreatureSpawner spawner = (CreatureSpawner) state;
                spawnerActionData.entityType = spawner.getSpawnedType().name().toLowerCase();
                spawnerActionData.delay = spawner.getDelay();
                actionData = spawnerActionData;
                break;
            case PLAYER_WALL_HEAD:
            case PLAYER_HEAD:
                SkullActionData headActionData = new SkullActionData();
                if (state instanceof Skull) {
                    Skull skull = ((Skull) state);
                    if (skull.getOwningPlayer() != null) {
                        headActionData.owner = skull.getOwningPlayer().getUniqueId().toString();
                    }
                }
                setBlockRotation(state, headActionData);
                actionData = headActionData;
                break;
            case SKELETON_SKULL:
            case SKELETON_WALL_SKULL:
            case WITHER_SKELETON_SKULL:
            case WITHER_SKELETON_WALL_SKULL:
                SkullActionData skullActionData = new SkullActionData();
                setBlockRotation(state, skullActionData);
                actionData = skullActionData;
                break;
            case COMMAND_BLOCK:
                final CommandBlock cmdBlock = (CommandBlock) state;
                final CommandActionData commandActionData = new CommandActionData();
                commandActionData.command = cmdBlock.getCommand();
                actionData = commandActionData;
                break;
            default:
                if (Tag.SIGNS.isTagged(state.getType())) {
                    final SignActionData signActionData = new SignActionData();
                    final Sign sign = (Sign) state;
                    signActionData.lines = sign.getLines();
                    actionData = signActionData;
                }
                break;
        }
        if (state instanceof Nameable && ((Nameable) state).getCustomName() != null) {
            if (actionData == null) {
                actionData = new BlockActionData();
            }
            actionData.customName = ((Nameable) state).getCustomName();
        }
    }

    private void setBlockRotation(BlockState block, SkullActionData skullActionData) {
        if (block.getBlockData() instanceof Rotatable) {
            final Rotatable r = (Rotatable) block.getBlockData();
            skullActionData.rotation = r.getRotation().toString();
        } else {
            final Directional d = (Directional) block.getBlockData();
            skullActionData.rotation = d.getFacing().name().toLowerCase();
        }
    }


    @Override
    public boolean hasExtraData() {
        return actionData != null;
    }

    @Override
    public String serialize() {
        return gson().toJson(actionData);
    }

    @Override
    public void deserialize(String data) {
        if (data != null && data.startsWith("{")) {
            if (getMaterial() == PLAYER_HEAD || getMaterial() == PLAYER_WALL_HEAD) {
                actionData = gson().fromJson(data, SkullActionData.class);
            } else if (getMaterial() == SPAWNER) {
                actionData = gson().fromJson(data, SpawnerActionData.class);
            } else if (Tag.SIGNS.isTagged(getMaterial())) {
                actionData = gson().fromJson(data, SignActionData.class);
            } else if (getMaterial() == COMMAND_BLOCK) {
                actionData = new CommandActionData();
                ((CommandActionData) actionData).command = data;
            } else {
                actionData = gson().fromJson(data,BlockActionData.class);
            }
        }
    }

    private BlockActionData getActionData() {
        return actionData;
    }


    @Override
    public String getNiceName() {
        String name = "";
        BlockActionData blockActionData = getActionData();
        if (blockActionData != null) {
            if (blockActionData instanceof SkullActionData) {
                final SkullActionData ad = (SkullActionData) blockActionData;
                name += ad.skullType + " ";
            } else if (blockActionData instanceof SpawnerActionData) {
                final SpawnerActionData ad = (SpawnerActionData) blockActionData;
                name += ad.entityType + " ";
            }
        }
        name += Prism.getItems().getAlias(getMaterial(), getBlockData());
        if (blockActionData == null) {
            return name;
        }
        if (blockActionData instanceof SignActionData) {
            final SignActionData ad = (SignActionData) blockActionData;
            if (ad.lines != null && ad.lines.length > 0) {
                name += " (" + TypeUtils.join(ad.lines, ", ") + ")";
            }
        } else if (blockActionData instanceof CommandActionData) {
            final CommandActionData ad = (CommandActionData) blockActionData;
            name += " (" + ad.command + ")";
        }
        if (blockActionData.customName != null) {
            name += ChatColor.RESET + " (" + blockActionData.customName + ChatColor.RESET + ") ";
        }
        if (getActionType().getName().equals("crop-trample") && getMaterial() == AIR) {
            return "empty soil";
        }
        return name;
    }

    @Override
    public String getCustomDesc() {
        if (getActionType().getName().equals("water-bucket") && getBlockData() instanceof Waterlogged) {
            return "waterlogged";
        }

        return null;
    }

    @Override
    public ChangeResult applyRollback(Player player, QueryParameters parameters, boolean isPreview) {
        final Block block = getWorld().getBlockAt(getLoc());
        if (getActionType().doesCreateBlock()) {
            return removeBlock(player, parameters, isPreview, block);
        } else {
            return placeBlock(player, parameters, isPreview, block, false);
        }
    }

    @Override
    public ChangeResult applyRestore(Player player, QueryParameters parameters, boolean isPreview) {
        final Block block = getWorld().getBlockAt(getLoc());
        if (getActionType().doesCreateBlock()) {
            return placeBlock(player, parameters, isPreview, block, false);
        } else {
            return removeBlock(player, parameters, isPreview, block);
        }
    }

    @Override
    public ChangeResult applyUndo(Player player, QueryParameters parameters, boolean isPreview) {

        final Block block = getWorld().getBlockAt(getLoc());

        // Undo a drain/ext event (which always remove blocks)
        // @todo if we ever track rollback/restore for undo, we'll
        // need logic to do the opposite
        return placeBlock(player, parameters, isPreview, block, false);

    }

    @Override
    public ChangeResult applyDeferred(Player player, QueryParameters parameters, boolean isPreview) {
        final Block block = getWorld().getBlockAt(getLoc());
        return placeBlock(player, parameters, isPreview, block, true);
    }

    ChangeResult placeBlock(Player player, QueryParameters parameters, boolean isPreview, Block block,
                            boolean isDeferred) {
        BlockStateChange stateChange;

        // Ensure block action is allowed to place a block here.
        // (essentially liquid/air).

        final boolean cancelIfBadPlace = !getActionType().requiresHandler(BlockChangeAction.class)
                && !getActionType().requiresHandler(PrismRollbackAction.class) && !parameters.hasFlag(Flag.OVERWRITE);

        if (cancelIfBadPlace && !Utilities.isAcceptableForBlockPlace(block.getType())) {
            Prism.debug("Block skipped due to being unacceptable for block place.: " + block.getType().name());
            return new ChangeResult(ChangeResultType.SKIPPED, null);
        }

        // On the blacklist (except an undo)
        if (Prism.getIllegalBlocks().contains(getMaterial())
                && !parameters.getProcessType().equals(PrismProcessType.UNDO)) {
            Prism.debug("Block skipped because it's not allowed to be placed unless its an UNDO."
                    + block.getType().name());
            return new ChangeResult(ChangeResultType.SKIPPED, null);
        }
        // If we're not in a preview, actually apply this block
        // Capture the block before we change it
        final BlockState originalBlock = block.getState();
        if (!isPreview) {
            return handleApply(block, originalBlock, parameters, cancelIfBadPlace);
        } else {

            // Otherwise, save the state so we can cancel if needed
            // Note: we save the original state as both old/new so we can re-use
            // blockStateChanges
            stateChange = new BlockStateChange(originalBlock, originalBlock);

            // Preview it
            EntityUtils.sendBlockChange(player, block.getLocation(), getBlockData());

            // Send preview to shared players
            for (final CommandSender sharedPlayer : parameters.getSharedPlayers()) {
                if (sharedPlayer instanceof Player) {
                    EntityUtils.sendBlockChange((Player) sharedPlayer, block.getLocation(), getBlockData());
                }
            }
            return new ChangeResult(ChangeResultType.APPLIED, stateChange);
        }
    }

    /**
     * The BlockState object is modified by this method.
     *
     * @param block            Block
     * @param originalBlock    BlockState
     * @param parameters       QueryParameters
     * @param cancelIfBadPlace cancelIfBadPlace
     * @return ChangeResult.
     */
    private @NotNull ChangeResult handleApply(final Block block, final BlockState originalBlock,
                                     final QueryParameters parameters, final boolean cancelIfBadPlace) {
        BlockState state = block.getState();
        // If lily pad, check that block below is water. Be sure
        // it's set to stationary water so the lily pad will sit
        switch (getMaterial()) {
            case LILY_PAD:
                final Block below = block.getRelative(BlockFace.DOWN);
                if (below.getType().equals(WATER) || below.getType().equals(AIR)) {
                    below.setType(WATER);
                } else {
                    // Prism.debug("Lilypad skipped because no water exists below.");
                    return new ChangeResult(ChangeResultType.SKIPPED, null);
                }
                break;
            case NETHER_PORTAL: // Only way is to set the portal on fire.
                final Block obsidian = Utilities.getFirstBlockOfMaterialBelow(OBSIDIAN, block.getLocation());
                if (obsidian != null) {
                    final Block above = obsidian.getRelative(BlockFace.UP);
                    if (!(above.getType() == NETHER_PORTAL)) {
                        above.setType(FIRE);
                        return new ChangeResult(ChangeResultType.APPLIED, null);
                    }
                }
                break;
            case JUKEBOX:
                setBlockData(Bukkit.createBlockData(JUKEBOX));
                break;
            default:
                break;

        }
        state.setType(getMaterial());
        state.setBlockData(getBlockData());
        state.update(true);
        BlockState newState = block.getState();
        BlockActionData blockActionData = getActionData();

        if ((getMaterial() == PLAYER_HEAD || getMaterial() == PLAYER_WALL_HEAD)
                && blockActionData instanceof SkullActionData) {
            return handleSkulls(block, blockActionData, originalBlock);
        }

        if (getMaterial() == SPAWNER && blockActionData instanceof SpawnerActionData) {

            final SpawnerActionData s = (SpawnerActionData) blockActionData;

            // Set spawner data
            ((CreatureSpawner) newState).setDelay(s.getDelay());
            ((CreatureSpawner) newState).setSpawnedType(s.getEntityType());

        }

        if (getMaterial() == COMMAND_BLOCK
                && blockActionData instanceof CommandActionData) {
            final CommandActionData c = (CommandActionData) blockActionData;
            ((CommandBlock) newState).setCommand(c.command);
        }
        if (newState instanceof Nameable && actionData.customName != null) {
            ((Nameable) newState).setCustomName(actionData.customName);
        }
        if (parameters.getProcessType() == PrismProcessType.ROLLBACK
                && Tag.SIGNS.isTagged(getMaterial())
                && blockActionData instanceof SignActionData) {

            final SignActionData s = (SignActionData) blockActionData;
            // Verify block is sign. Rarely, if the block somehow pops off
            // or fails
            // to set it causes ClassCastException:
            // org.bukkit.craftbukkit.v1_4_R1.block.CraftBlockState
            // cannot be cast to org.bukkit.block.Sign
            // https://snowy-evening.com/botsko/prism/455/
            if (newState instanceof Sign) {
                if (s.lines != null) {
                    for (int i = 0; i < s.lines.length; ++i) {
                        ((Sign) newState).setLine(i, s.lines[i]);
                    }
                }
            }
        }

        // -----------------------------
        // Sibling logic marker

        // If the material is a crop that needs soil, we must restore the soil
        // This may need to go before setting the block, but I prefer the BlockUtil logic to use materials.
        BlockState sibling = null;

        if (Utilities.materialRequiresSoil(getMaterial())) {
            sibling = block.getRelative(BlockFace.DOWN).getState();

            if (cancelIfBadPlace && !MaterialTag.SOIL_CANDIDATES.isTagged(sibling.getType())) {
                Prism.debug(parameters.getProcessType().name() + " skipped due to lack of soil for "
                        + getMaterial().name());
                return new ChangeResult(ChangeResultType.SKIPPED, null);
            }
            sibling.setType(FARMLAND);
        }

        // Chest sides can be broken independently, ignore them
        if (newState.getType() != CHEST && newState.getType() != TRAPPED_CHEST) {
            final Block s = Utilities.getSiblingForDoubleLengthBlock(state);

            if (s != null) {
                sibling = s.getState();

                if (cancelIfBadPlace && !Utilities.isAcceptableForBlockPlace(sibling.getType())) {
                    Prism.debug(parameters.getProcessType().name() + " skipped due to lack of wrong sibling type for "
                            + getMaterial().name());
                    return new ChangeResult(ChangeResultType.SKIPPED, null);
                }

                sibling.setType(block.getType());

                BlockData siblingData = getBlockData().clone();

                if (siblingData instanceof Bed) {
                    // We always log the foot
                    ((Bed) siblingData).setPart(Part.HEAD);
                } else if (siblingData instanceof Bisected) {
                    // We always log the bottom
                    ((Bisected) siblingData).setHalf(Half.TOP);
                }

                sibling.setBlockData(siblingData);
            }
        }

        boolean physics = !parameters.hasFlag(Flag.NO_PHYS);

        newState.update(true, physics);

        if (sibling != null) {
            sibling.update(true, physics);
        }
        return new ChangeResult(ChangeResultType.APPLIED,new BlockStateChange(originalBlock,state));
    }

    private @NotNull ChangeResult handleSkulls(final Block block, BlockActionData blockActionData,
                                               final BlockState originalBlock) {
        block.setType(getMaterial());
        BlockState state = block.getState();
        final SkullActionData s = (SkullActionData) blockActionData;

        if (state.getBlockData() instanceof Rotatable) {
            final Rotatable r = (Rotatable) state.getBlockData();
            r.setRotation(s.getRotation());
            state.setBlockData(r);
        } else {
            final Directional d = (Directional) state.getBlockData();
            d.setFacing(s.getRotation());
            state.setBlockData(d);
        }
        state = block.getState();

        if (!s.owner.isEmpty()) {
            final Skull skull = (Skull) state;
            skull.setOwningPlayer(Bukkit.getOfflinePlayer(EntityUtils.uuidOf((s.owner))));
        }
        BlockStateChange stateChange = new BlockStateChange(originalBlock, state);
        return new ChangeResult(ChangeResultType.APPLIED, stateChange);
    }

    private ChangeResult removeBlock(Player player, QueryParameters parameters, boolean isPreview, Block block) {

        BlockStateChange stateChange;

        if (!block.getType().equals(AIR)) {

            // Ensure it's acceptable to remove the current block
            if (!Utilities.isAcceptableForBlockPlace(block.getType())
                    && !Utilities.areBlockIdsSameCoreItem(block.getType(), getMaterial())
                    && !parameters.hasFlag(Flag.OVERWRITE)) {
                return new ChangeResult(ChangeResultType.SKIPPED, null);
            }
            // Capture the block before we change it

            final BlockState originalBlock = block.getState();
            if (!isPreview) {
                // Set
                block.setType(AIR);
                // Capture the new state
                final BlockState newBlock = block.getState();
                // Store the state change
                stateChange = new BlockStateChange(originalBlock, newBlock);
            } else {
                // Otherwise, save the state so we can cancel if needed
                // Note: we save the original state as both old/new so we can
                // re-use blockStateChanges
                stateChange = new BlockStateChange(originalBlock, originalBlock);

                // Preview it
                EntityUtils.sendBlockChange(player, block.getLocation(), Bukkit.createBlockData(AIR));

                // Send preview to shared players
                for (final CommandSender sharedPlayer : parameters.getSharedPlayers()) {
                    if (sharedPlayer instanceof Player) {
                        EntityUtils.sendBlockChange((Player) sharedPlayer, block.getLocation(),
                                Bukkit.createBlockData(AIR));
                    }
                }
            }
            return new ChangeResult(ChangeResultType.APPLIED, stateChange);
        }
        return new ChangeResult(ChangeResultType.SKIPPED, null);
    }

    /**
     * BlockActionData.
     *
     * @author botskonet
     */
    static class BlockActionData {
        String customName;
    }

    public static class CommandActionData extends BlockActionData {
        String command;
    }

    /**
     * Spawner ActionData.
     *
     * @author botskonet
     */
    public static class SpawnerActionData extends BlockActionData {

        String entityType;
        int delay;

        EntityType getEntityType() {
            return EntityType.valueOf(entityType.toUpperCase());
        }

        int getDelay() {
            return delay;
        }
    }

    /**
     * SkullActionData.
     *
     * @author botskonet
     */
    public static class SkullActionData extends BlockActionData {

        String rotation;
        String owner;
        String skullType;

        BlockFace getRotation() {
            if (rotation != null) {
                return BlockFace.valueOf(rotation.toUpperCase());
            }
            return null;
        }
    }

    /**
     * Not to be confused with SignChangeActionData, which records additional data
     * we don't need here.
     *
     * @author botskonet
     */
    public static class SignActionData extends BlockActionData {
        String[] lines;
    }
}

package me.botsko.prism.actions;

import me.botsko.prism.Prism;
import me.botsko.prism.actionlibs.QueryParameters;
import me.botsko.prism.appliers.ChangeResult;
import me.botsko.prism.appliers.ChangeResultType;
import me.botsko.prism.appliers.PrismProcessType;
import me.botsko.prism.commandlibs.Flag;
import me.botsko.prism.utils.block.Utilities;
import org.bukkit.Material;
import org.bukkit.block.Block;
import org.bukkit.block.data.BlockData;
import org.bukkit.entity.Player;

public class BlockChangeAction extends BlockAction {

    @Override
    public String getNiceName() {
        String name;
        if (this.getActionType().getName().equals("block-fade")) {
            name = Prism.getItems().getAlias(getOldMaterial(), getOldBlockData());
        } else {
            name = super.getNiceName();
        }
        return name;
    }

    @Override
    public ChangeResult applyRollback(Player player, QueryParameters parameters, boolean isPreview) {
        final Block block = getWorld().getBlockAt(getLoc());
        return placeBlock(player, parameters, isPreview, getActionType().getName(), getOldMaterial(), getOldBlockData(),
                getMaterial(), getBlockData(), block, false);
    }

    @Override
    public ChangeResult applyRestore(Player player, QueryParameters parameters, boolean isPreview) {
        final Block block = getWorld().getBlockAt(getLoc());
        return placeBlock(player, parameters, isPreview, getActionType().getName(), getOldMaterial(), getOldBlockData(),
                getMaterial(), getBlockData(), block, false);
    }

    @Override
    public ChangeResult applyUndo(Player player, QueryParameters parameters, boolean isPreview) {
        final Block block = getWorld().getBlockAt(getLoc());
        return placeBlock(player, parameters, isPreview, getActionType().getName(), getOldMaterial(), getOldBlockData(),
                getMaterial(), getBlockData(), block, false);
    }

    @Override
    public ChangeResult applyDeferred(Player player, QueryParameters parameters, boolean isPreview) {
        final Block block = getWorld().getBlockAt(getLoc());
        return placeBlock(player, parameters, isPreview, getActionType().getName(), getOldMaterial(), getOldBlockData(),
                getMaterial(), getBlockData(), block, true);
    }

    private ChangeResult placeBlock(Player player, QueryParameters parameters, boolean isPreview, String type,
                                    Material oldMat, BlockData oldData, Material newMat, BlockData newData, Block block,
                                    boolean isDeferred) {

        final BlockAction b = new BlockAction();
        b.setActionType(type);
        b.setLoc(getLoc());
        if (parameters.getProcessType().equals(PrismProcessType.ROLLBACK)) {
            // Run verification for no-overwrite. Only reverse a change
            // if the opposite state is what's present now.
            // We skip this check because if we're in preview mode the block may
            // not have been properly changed yet.
            return processChange(player, parameters, isPreview, newMat, oldMat, oldData, block, isDeferred, b);
        }
        if (parameters.getProcessType().equals(PrismProcessType.RESTORE)) {
            return processChange(player, parameters, isPreview, oldMat, newMat, newData, block, isDeferred, b);
        }
        if (parameters.getProcessType().equals(PrismProcessType.UNDO)) {
            b.setMaterial(oldMat);
            b.setBlockData(oldData);
            return b.placeBlock(player, parameters, isPreview, block, isDeferred);
        }
        return new ChangeResult(ChangeResultType.SKIPPED, null);
    }

    private ChangeResult processChange(Player player, QueryParameters parameters, boolean isPreview,
                                       Material originalMaterial, Material replacedMaterial, BlockData replacedData,
                                       Block currentBlock, boolean isDeferred, BlockAction action) {
        if (Utilities.isAcceptableForBlockPlace(currentBlock.getType())
                || Utilities.areBlockIdsSameCoreItem(currentBlock.getType(), originalMaterial) || isPreview
                || parameters.hasFlag(Flag.OVERWRITE)) {
            action.setMaterial(replacedMaterial);
            action.setBlockData(replacedData);
            return action.placeBlock(player, parameters, isPreview, currentBlock, isDeferred);
        } else {
            Prism.debug("Skipped Change for " + parameters.getProcessType().name() + " because current-> "
                    + currentBlock.getType() + " != " + originalMaterial.name() + " <- what we think we will replace.");
            return new ChangeResult(ChangeResultType.SKIPPED, null);
        }
    }
}

package me.botsko.prism.utils;

import me.botsko.prism.Prism;
import me.botsko.prism.database.IdMapQuery;
import me.botsko.prism.database.sql.SqlIdMapQuery;
import me.botsko.prism.utils.block.Utilities;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.block.data.BlockData;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.inventory.ItemStack;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Map.Entry;
import java.util.Set;

public class MaterialAliases {
    private static final int SUBID_WILDCARD = -1;
    private final Map<String, String> matCache = new HashMap<>();
    private final Map<String, String> idCache = new HashMap<>();
    private final Map<Material, Set<IntPair>> allIdsCache = new HashMap<>();

    private final HashMap<String, String> itemAliases = new HashMap<>();

    /**
     * Load the yml file and save config to hashmap.
     */
    public MaterialAliases() {
        FileConfiguration items = null;
        InputStream defConfigStream = this.getClass().getResourceAsStream("/items.yml");
        if (defConfigStream != null) {
            System.out.println("Elixr: Loaded items directory");
            items = YamlConfiguration.loadConfiguration(new InputStreamReader(defConfigStream));
        }


        if (items != null) {

            // Load all item ids/aliases
            ConfigurationSection sec = items.getConfigurationSection("items");
            Map<String, Object> itemAliases = null;

            if (sec != null) {
                itemAliases = sec.getValues(false);
            }
            // Cache the values for easier lookup
            if (itemAliases != null) {
                for (Map.Entry<String, Object> entry : itemAliases.entrySet()) {
                    @SuppressWarnings("unchecked")
                    Iterable<String> aliases = (List<String>) entry.getValue();

                    for (String alias : aliases) {
                        this.itemAliases.put(entry.getKey().toLowerCase(), alias);
                    }
                }
            }

        } else {
            Prism.getPrismDataSource().getLog().error(
                    "ERROR: The Item library was unable to load an internal item alias list.");
        }
    }

    public void initAllMaterials() {
        initMaterials(Material.values());
    }

    /**
     * Initialize the library.
     *
     * @param materials Materials ...
     */
    public void initMaterials(Material... materials) {
        Bukkit.getScheduler().runTaskAsynchronously(Prism.getInstance(), () -> {
            SqlIdMapQuery query = new SqlIdMapQuery(Prism.getPrismDataSource());
            for (Material m : materials) {
                String matName = m.name().toLowerCase(Locale.ENGLISH);
                String dataString;

                try {
                    dataString = Utilities.dataString(Bukkit.createBlockData(m));
                } catch (IllegalArgumentException e) {
                    continue;
                }

                query.findIds(m.name().toLowerCase(Locale.ENGLISH), dataString, (i, d) ->
                        storeCache(m, dataString, i, d), () -> {
                          int id = query.mapAutoId(matName, dataString);
                          storeCache(m, dataString, id, 0);
                    });
            }
        });

    }

    private Set<IntPair> getIdsOf(Material material) {
        Set<IntPair> ids = allIdsCache.get(material);
        if (ids != null) {
            return ids;
        }

        IdMapQuery query = new SqlIdMapQuery(Prism.getPrismDataSource());

        query.findAllIds(material.name().toLowerCase(Locale.ENGLISH), list -> allIdsCache.put(
                material, new HashSet<>(list)));
        return allIdsCache.get(material);
    }

    private void storeCache(Material material, String state, int blockId, int blockSubid) {
        String matKey = material.name().toLowerCase(Locale.ENGLISH) + ":" + state;
        String idKey = blockId + ":" + blockSubid;

        matCache.put(idKey, matKey);
        idCache.put(matKey, idKey);

        getIdsOf(material).add(new IntPair(blockId, blockSubid));
    }

    private MaterialState fromCache(int blockId, int blockSubid) {
        String value = matCache.get(blockId + ":" + blockSubid);

        if (value != null) {
            String[] parts = value.split(":", 2);

            return new MaterialState(Material.matchMaterial(parts[0]), parts[1]);
        }

        return null;
    }

    private IntPair fromCache(Material material, String state) {
        String value = idCache.get(material.name().toLowerCase(Locale.ENGLISH) + ":" + state);

        if (value != null) {
            String[] parts = value.split(":", 2);

            return new IntPair(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
        }

        return null;
    }

    /**
     * .
     *
     * @param blockId           int
     * @param blockSubId        logMaterialErrorsint
     * @param logMaterialErrors boolean.
     * @return MaterialState
     */
    public MaterialState idsToMaterial(int blockId, int blockSubId, Boolean logMaterialErrors) {
        MaterialState cachedMaterial = fromCache(blockId, blockSubId);

        if (cachedMaterial != null) {
            return cachedMaterial;
        }

        MaterialState result = new MaterialState();
        SqlIdMapQuery query = new SqlIdMapQuery(Prism.getPrismDataSource());

        query.findMaterial(blockId, blockSubId, (material, state) -> {
            result.material = Material.matchMaterial(material.toUpperCase(Locale.ENGLISH));
            result.state = state;
            if (result.material != null) {
                storeCache(result.material, result.state, blockId, blockSubId);
            }
        }, () -> {
                if (logMaterialErrors) {
                    Prism.log("matError: [" + blockId + ", " + blockSubId + "] -> ???");
                }
            });

        if (result.material == null) {
            return null;
        }

        return result;
    }

    /**
     * Create IntPair.
     *
     * @param material Material
     * @param state    State
     * @return IntPair
     */
    public IntPair materialToIds(Material material, String state) {
        int blockSubId;

        // For tools, where durability doesn't mean a different item (different cached
        // value) but is still important
        int durability = 0;
        try {
            durability = Integer.parseInt(state);
        } catch (NumberFormatException ignored) {
            //ignored
        }

        if (material.getMaxDurability() > 0) {
            blockSubId = 0;
        } else {
            blockSubId = durability;
        }

        IntPair cachedIds = fromCache(material, blockSubId == 0 ? state : String.valueOf(blockSubId));

        if (cachedIds != null) {
            return cachedIds;
        }

        IntPair result = new IntPair(0, 0);
        SqlIdMapQuery query = new SqlIdMapQuery(Prism.getPrismDataSource());
        String materialName = material.name().toLowerCase(Locale.ENGLISH);

        synchronized (this) {
            query.findIds(materialName, state, (queryId, querySubId) -> {
                result.first = queryId;
                result.second = querySubId;
                storeCache(material, state, queryId, querySubId);
            },
                  () -> {
                      int blockId = query.mapAutoId(materialName, state);
                      result.first = blockId;
                      storeCache(material, state, blockId, 0);
                  });
        }

        if (blockSubId != durability) {
            result.second = durability;
        }
        return result;
    }

    public Set<IntPair> materialToAllIds(Material material) {
        return Collections.unmodifiableSet(getIdsOf(material));
    }

    /**
     * .
     *
     * @param material         Material
     * @param partialBlockData String
     * @return Set of IntPair
     * @throws IllegalArgumentException exception
     */
    public Set<IntPair> partialBlockDataIds(Material material, String partialBlockData)
            throws IllegalArgumentException {
        String fullBlockData = Utilities.dataString(Bukkit.createBlockData(material, partialBlockData));

        String[] parts = fullBlockData.substring(1, fullBlockData.length() - 1).toLowerCase(Locale.ENGLISH).split(",");

        StringBuilder likeString = new StringBuilder("%");

        for (String string : parts) {
            if (partialBlockData.contains(string)) {
                likeString.append(string).append('%');
            }
        }

        String stateLike = likeString.toString();

        IdMapQuery query = new SqlIdMapQuery(Prism.getPrismDataSource());

        Set<IntPair> ids = new HashSet<>();
        query.findAllIdsPartial(material.name().toLowerCase(Locale.ENGLISH), stateLike, ids::addAll);

        return ids;
    }

    /**
     * .
     *
     * @param material Material
     * @param state    String
     * @return IntPair
     */
    @Deprecated
    public IntPair materialToIdsWildcard(Material material, String state) {
        IntPair ids = materialToIds(material, state);

        if (material.getMaxDurability() > 0) {
            ids.second = SUBID_WILDCARD;
        }
        return ids;
    }

    /**
     * Returns the loaded list of item aliases/ids.
     *
     * @return HashMap
     */
    @Deprecated
    public HashMap<String, String> getItemAliases() {
        return itemAliases;
    }

    /**
     * .
     *
     * @param material Material
     * @param data     BlockData
     * @return String
     */
    public String getAlias(Material material, BlockData data) {
        String dataString = Utilities.dataString(data);

        String itemName = null;
        if (!itemAliases.isEmpty()) {
            String key = material.name().toLowerCase() + dataString;
            itemName = itemAliases.get(key);
        }
        if (itemName == null) {
            itemName = material.name().toLowerCase().replace("_", " ");
        }
        return itemName;
    }

    /**
     * Returns the proper name given an item stack.
     *
     * @param i ItemStack
     * @return String
     */
    public String getAlias(ItemStack i) {
        return i.getType().name().toLowerCase().replace("_", " ");
    }

    /**
     * .
     *
     * @param alias String
     * @return ArrayList
     */
    // TODO: Break this in 1.13. Woooo.
    public ArrayList<Material> getMaterialsByAlias(String alias) {
        ArrayList<Material> itemIds = new ArrayList<>();
        if (!itemAliases.isEmpty()) {
            for (Entry<String, String> entry : itemAliases.entrySet()) {
                if (entry.getValue().equals(alias)) {
                    itemIds.add(Material.matchMaterial(entry.getKey()));
                }
            }
        }
        return itemIds;
    }

    public static class MaterialState {
        public Material material;
        public String state;

        protected MaterialState() {
        }

        public MaterialState(Material material, String state) {
            this.material = material;
            this.state = state;
        }

        /**
         * Get BlockData.
         *
         * @return BlockData
         */
        public BlockData asBlockData() {
            try {
                BlockData data = Bukkit.createBlockData(material, state);

                // In the event that we tried to get BlockData for an item and it returned air
                if (data.getMaterial() == material) {
                    return data;
                }
            } catch (IllegalArgumentException ignored) {
                //ignored
            }

            return null;
        }

        /**
         * Get as Item.
         *
         * @return ItemStack
         */
        public ItemStack asItem() {
            ItemStack item = new ItemStack(material, 1);

            if (!state.isEmpty()) {
                try {
                    ItemUtils.setItemDamage(item, Short.parseShort(state));
                } catch (NumberFormatException ignored) {
                    //ignored
                }

            }

            return item;
        }

        @Override
        public String toString() {
            return material.name().toLowerCase(Locale.ENGLISH) + state;
        }

        @Override
        public int hashCode() {
            return toString().hashCode();
        }
    }
}

