			port = Integer.parseInt(prop.getProperty("port"));
		} catch (FileNotFoundException e) {
			e.printStackTrace();
			this.saveConfigToDisk(true);
			this.loadConfigFromDisk();
		} catch (IOException e) {
			EnderLogger.exception(e);
		}
		return prop;
