	@Override
	public void run() {
		Main.instance = this;
		EnderLogger.info("Starting " + NAME + " " + VERSION + " server version " + PROTOCOL_VERSION + ".");
		EnderLogger.info("Authors: " + Arrays.asList(AUTHORS).toString());
		EnderLogger.info("Loading config.ender file...");
		this.loadConfigFromDisk();
