		if (!isGranted(Permission.accessControl, ctx)) {
			throw new FrameworkException(403, "Access control not permitted");
		}

		clearCaches();

		Security secRel = getSecurityRelationship(principal);
		if (secRel != null) {

			secRel.removePermissions(permissions);
		}
	}


