    public Matrix power(int n, Factory factory) {
        if (n < 0) {
            fail("The exponent should be positive: " + n + ".");
        }

        Matrix result = factory.createIdentityMatrix(rows);
        Matrix that = this;

        while (n > 0) {
            if (n % 2 == 1) {
                result = result.multiply(that);
            }

            n /= 2;
            that = that.multiply(that);
        }

        return result;
    }

