        System.arraycopy(columnIndices, 0, $columnIndices, 0, cardinality);
        System.arraycopy(rowPointers, 0, $rowPointers, 0, rows + 1);

        return new CRSMatrix(rows, columns, cardinality, $values, 
                             $columnIndices, $rowPointers);
    }

