    @Test
    public void testSwap_3x3() {

        Matrix a = factory().createMatrix(new double[][]{
                {1.0, 0.0, 0.0},
                {0.0, 5.0, 0.0},
                {0.0, 0.0, 9.0}
        });

        Matrix b = factory().createMatrix(new double[][]{
                {0.0, 0.0, 9.0},
                {0.0, 5.0, 0.0},
                {1.0, 0.0, 0.0}
        });

        Matrix c = factory().createMatrix(new double[][]{
                {9.0, 0.0, 0.0},
                {0.0, 5.0, 0.0},
                {0.0, 0.0, 1.0}
        });

        a.swapRows(0, 2);
        assertEquals(b, a);

        b.swapColumns(0, 2);
        assertEquals(c, b);
    }

