    @Test
    public void testTranspose_4x4() {

        Matrix a = factory().createMatrix(new double[][]{
                {0.0, 14.2, 0.0, 4.0},
                {0.0, 5.0, 10.0, 0.0},
                {0.0, 3.0, 0.0, 2.3},
                {11.0, 7.0, 0.0, 1.0}
        });

        Matrix b = factory().createMatrix(new double[][]{
                {0.0, 0.0, 0.0, 11.0},
                {14.2, 5.0, 3.0, 7.0},
                {0.0, 10.0, 0.0, 0.0},
                {4.0, 0.0, 2.3, 1.0}
        });

        Matrix c = a.transpose();
        assertEquals(b, c);

        Matrix d = c.transpose();
        assertEquals(a, d);
    }

    @Test
