                {14.2, 5.0, 3.0, 7.0, 7.5},
                {0.0, 10.0, 0.0, 0.0, 0}
        });

        Matrix c = a.transpose();
        assertEquals(b, c);

        Matrix d = c.transpose();
        assertEquals(a, d);
    }

