        });

        Matrix b = factory().createMatrix(new double[][]{
                {11.0, 10.0, 10.0},
                {10.0, 15.0, 10.0},
                {10.0, 10.0, 19.0}
        });

        Matrix c = factory().createMatrix(new double[][]{
                {2.0, 0.0, 0.0},
