        { actuatorProfiles = new ReferenceActuatorProfiles();
        }
        return actuatorProfiles;
    }

    public void setActuatorProfiles(ReferenceActuatorProfiles actuatorProfiles) {
        this.actuatorProfiles = actuatorProfiles;
