        ch.close( bungee.getTranslation( "outdated_client", bungee.getGameVersion() ) );
    }

    @Override
    public void handle(LegacyPing ping) throws Exception
    {
        this.legacy = true;
        final boolean v1_5 = ping.isV1_5();

        ServerPing legacy = new ServerPing( new ServerPing.Protocol( bungee.getCustomBungeeName(), bungee.getProtocolVersion() ), //BotFilter
                new ServerPing.Players( listener.getMaxPlayers(), bungee.getOnlineCountBF( true ), null ), //BotFilter
                new TextComponent( TextComponent.fromLegacyText( listener.getMotd() ) ), (Favicon) null );

        Callback<ProxyPingEvent> callback = new Callback<ProxyPingEvent>()
        {
            @Override
            public void done(ProxyPingEvent result, Throwable error)
            {
                if ( ch.isClosed() )
                {
                    return;
                }

                ServerPing legacy = result.getResponse();
                String kickMessage;

                if ( v1_5 )
                {
                    kickMessage = ChatColor.DARK_BLUE
                            + "\00" + 127
                            + '\00' + legacy.getVersion().getName()
                            + '\00' + getFirstLine( legacy.getDescription() )
                            + '\00' + legacy.getPlayers().getOnline()
                            + '\00' + legacy.getPlayers().getMax();
                } else
                {
                    // Clients <= 1.3 don't support colored motds because the color char is used as delimiter
                    kickMessage = ChatColor.stripColor( getFirstLine( legacy.getDescription() ) )
                            + '\u00a7' + legacy.getPlayers().getOnline()
                            + '\u00a7' + legacy.getPlayers().getMax();
                }

                ch.close( kickMessage );
            }
        };

        bungee.getPluginManager().callEvent( new ProxyPingEvent( this, legacy, callback ) );
    }

    private static String getFirstLine(String str)
    {
        int pos = str.indexOf( '\n' );
        return pos == -1 ? str : str.substring( 0, pos );
    }

    @Override
    public void handle(StatusRequest statusRequest) throws Exception
    {
        Preconditions.checkState( thisState == State.STATUS, "Not expecting STATUS" );

        ServerInfo forced = AbstractReconnectHandler.getForcedHost( this );
        final String motd = ( forced != null ) ? forced.getMotd() : listener.getMotd();

        Callback<ServerPing> pingBack = new Callback<ServerPing>()
        {
            @Override
            public void done(ServerPing result, Throwable error)
            {
                if ( error != null )
                {
                    result = new ServerPing();
                    result.setDescription( bungee.getTranslation( "ping_cannot_connect" ) );
                    bungee.getLogger().log( Level.WARNING, "Error pinging remote server", error );
                }

                Callback<ProxyPingEvent> callback = new Callback<ProxyPingEvent>()
                {
                    @Override
                    public void done(ProxyPingEvent pingResult, Throwable error)
                    {
                        Gson gson = BungeeCord.getInstance().gson;
                        unsafe.sendPacket( new StatusResponse( gson.toJson( pingResult.getResponse() ) ) );
                        if ( bungee.getConnectionThrottle() != null )
                        {
                            bungee.getConnectionThrottle().unthrottle( getAddress().getAddress() );
                        }
                    }
                };

                bungee.getPluginManager().callEvent( new ProxyPingEvent( InitialHandler.this, result, callback ) );
            }
        };

        if ( forced != null && listener.isPingPassthrough() )
        {
            ( (BungeeServerInfo) forced ).ping( pingBack, handshake.getProtocolVersion() );
        } else
        {
            int protocol = ( ProtocolConstants.SUPPORTED_VERSION_IDS.contains( handshake.getProtocolVersion() ) ) ? handshake.getProtocolVersion() : bungee.getProtocolVersion();
            pingBack.done( new ServerPing(
                    new ServerPing.Protocol( bungee.getCustomBungeeName(), protocol ), //BotFilter
                    new ServerPing.Players( listener.getMaxPlayers(), bungee.getOnlineCountBF( true ), null ), //BotFilter
                    motd, PingLimiter.handle() ? null : BungeeCord.getInstance().config.getFaviconObject() ), //BotFilter PingLimiter.handle() ? null :
                    null );
        }

        thisState = State.PING;
    }

    @Override
    public void handle(PingPacket ping) throws Exception
    {
        Preconditions.checkState( thisState == State.PING, "Not expecting PING" );
        unsafe.sendPacket( ping );
        disconnect( "" );
    }

    @Override
    public void handle(Handshake handshake) throws Exception
    {

        Preconditions.checkState( thisState == State.HANDSHAKE, "Not expecting HANDSHAKE" );
        this.handshake = handshake;
        ch.setVersion( handshake.getProtocolVersion() );

        // Starting with FML 1.8, a "\0FML\0" token is appended to the handshake. This interferes
        // with Bungee's IP forwarding, so we detect it, and remove it from the host string, for now.
        // We know FML appends \00FML\00. However, we need to also consider that other systems might
        // add their own data to the end of the string. So, we just take everything from the \0 character
        // and save it for later.
        if ( handshake.getHost().contains( "\0" ) )
        {
            String[] split = handshake.getHost().split( "\0", 2 );
            handshake.setHost( split[0] );
            extraDataInHandshake = "\0" + split[1];
        }

        // SRV records can end with a . depending on DNS / client.
        if ( handshake.getHost().endsWith( "." ) )
        {
            handshake.setHost( handshake.getHost().substring( 0, handshake.getHost().length() - 1 ) );
        }

        this.virtualHost = InetSocketAddress.createUnresolved( handshake.getHost(), handshake.getPort() );

        if ( bungee.getConfig().isLogPings() )
        {
            bungee.getLogger().log( Level.INFO, "{0} has connected", this );
        }

        bungee.getPluginManager().callEvent( new PlayerHandshakeEvent( InitialHandler.this, handshake ) );
        switch ( handshake.getRequestedProtocol() )
        {
            case 1:
                // Ping
                thisState = State.STATUS;
                ch.setProtocol( Protocol.STATUS );
                bungee.getBotFilter().getServerPingUtils().add( getAddress().getAddress() ); //BotFilter
                break;
            case 2:
                // Login
                if ( !bungee.getConfig().isLogPings() )
                {
                    bungee.getLogger().log( Level.INFO, "{0} has connected", this );
                }
                thisState = State.USERNAME;
                ch.setProtocol( Protocol.LOGIN );

                if ( !ProtocolConstants.SUPPORTED_VERSION_IDS.contains( handshake.getProtocolVersion() ) )
                {
                    if ( handshake.getProtocolVersion() > bungee.getProtocolVersion() )
                    {
                        disconnect( bungee.getTranslation( "outdated_server", bungee.getGameVersion() ) );
                    } else
                    {
                        disconnect( bungee.getTranslation( "outdated_client", bungee.getGameVersion() ) );
                    }
                    return;
                }
                break;
            default:
                throw new IllegalArgumentException( "Cannot request protocol " + handshake.getRequestedProtocol() );
        }
    }

    @Override
    public void handle(LoginRequest loginRequest) throws Exception
    {
        Preconditions.checkState( thisState == State.USERNAME, "Not expecting USERNAME" );
        this.loginRequest = loginRequest;

        bungee.getBotFilter().checkAsyncIfNeeded( this );
        //BotFilter moved code to delayedHandleOfLoginRequset();
    }

    public void delayedHandleOfLoginRequset()
    {
        if ( getName().contains( "." ) )
        {
            disconnect( bungee.getTranslation( "name_invalid" ) );
            return;
        }

        if ( getName().length() > 16 )
        {
            disconnect( bungee.getTranslation( "name_too_long" ) );
            return;
        }

        int limit = BungeeCord.getInstance().config.getPlayerLimit();
        if ( limit > 0 && bungee.getOnlineCountBF( false ) > limit )//BotFilter
        {
            disconnect( bungee.getTranslation( "proxy_full" ) );
            return;
        }

        // If offline mode and they are already on, don't allow connect
        // We can just check by UUID here as names are based on UUID
        if ( !isOnlineMode() && bungee.getPlayer( getUniqueId() ) != null )
        {
            disconnect( bungee.getTranslation( "already_connected_proxy" ) );
            return;
        }

        Callback<PreLoginEvent> callback = new Callback<PreLoginEvent>()
        {

            @Override
            public void done(PreLoginEvent result, Throwable error)
            {
                if ( result.isCancelled() )
                {
                    disconnect( result.getCancelReasonComponents() );
                    return;
                }
                if ( ch.isClosed() )
                {
                    return;
                }
                if ( onlineMode )
                {
                    unsafe().sendPacket( request = EncryptionUtil.encryptRequest() );
                } else if ( isInEventLoop() )
                {
                    finish();
                } else
                {
                    ch.getHandle().eventLoop().execute( () ->
                    {
                        if ( !ch.isClosing() )
                        {
                            finish();
                        }
                    } );
                }
                thisState = State.ENCRYPT;
            }
        };

        // fire pre login event
        bungee.getPluginManager().callEvent( new PreLoginEvent( InitialHandler.this, callback ) );

    }

    @Override
    public void handle(final EncryptionResponse encryptResponse) throws Exception
    {
        Preconditions.checkState( thisState == State.ENCRYPT, "Not expecting ENCRYPT" );

        SecretKey sharedKey = EncryptionUtil.getSecret( encryptResponse, request );
        BungeeCipher decrypt = EncryptionUtil.getCipher( false, sharedKey );
        ch.addBefore( PipelineUtils.FRAME_DECODER, PipelineUtils.DECRYPT_HANDLER, new CipherDecoder( decrypt ) );
        BungeeCipher encrypt = EncryptionUtil.getCipher( true, sharedKey );
        ch.addBefore( PipelineUtils.FRAME_PREPENDER, PipelineUtils.ENCRYPT_HANDLER, new CipherEncoder( encrypt ) );

        String encName = URLEncoder.encode( InitialHandler.this.getName(), "UTF-8" );

        MessageDigest sha = MessageDigest.getInstance( "SHA-1" );
        for ( byte[] bit : new byte[][]
        {
            request.getServerId().getBytes( "ISO_8859_1" ), sharedKey.getEncoded(), EncryptionUtil.keys.getPublic().getEncoded()
        } )
        {
            sha.update( bit );
        }
        String encodedHash = URLEncoder.encode( new BigInteger( sha.digest() ).toString( 16 ), "UTF-8" );

        String preventProxy = ( ( BungeeCord.getInstance().config.isPreventProxyConnections() ) ? "&ip=" + URLEncoder.encode( getAddress().getAddress().getHostAddress(), "UTF-8" ) : "" );
        String authURL = "https://sessionserver.mojang.com/session/minecraft/hasJoined?username=" + encName + "&serverId=" + encodedHash + preventProxy;

        Callback<String> handler = new Callback<String>()
        {
            @Override
            public void done(String result, Throwable error)
            {
                if ( error == null )
                {
                    LoginResult obj = BungeeCord.getInstance().gson.fromJson( result, LoginResult.class );
                    if ( obj != null && obj.getId() != null )
                    {
                        loginProfile = obj;
                        name = obj.getName();
                        uniqueId = Util.getUUID( obj.getId() );
                        finish();
                        return;
                    }
                    disconnect( bungee.getTranslation( "offline_mode_player" ) );
                } else
                {
                    disconnect( bungee.getTranslation( "mojang_fail" ) );
                    bungee.getLogger().log( Level.SEVERE, "Error authenticating " + getName() + " with minecraft.net", error );
                }
            }
        };

        HttpClient.get( authURL, ch.getHandle().eventLoop(), handler );
    }

    private void finish()
    {
        if ( isOnlineMode() )
        {
            // Check for multiple connections
            // We have to check for the old name first
            ProxiedPlayer oldName = bungee.getPlayer( getName() );
            if ( oldName != null )
            {
                // TODO See #1218
                oldName.disconnect( bungee.getTranslation( "already_connected_proxy" ) ); // TODO: Cache this disconnect packet
            }
            // And then also for their old UUID
            ProxiedPlayer oldID = bungee.getPlayer( getUniqueId() );
            if ( oldID != null )
            {
                // TODO See #1218
                oldID.disconnect( bungee.getTranslation( "already_connected_proxy" ) ); // TODO: Cache this disconnect packet
            }
        } else
        {
            // In offline mode the existing user stays and we kick the new one
            ProxiedPlayer oldName = bungee.getPlayer( getName() );
            if ( oldName != null )
            {
                // TODO See #1218
                disconnect( bungee.getTranslation( "already_connected_proxy" ) ); // TODO: Cache this disconnect packet
                return;
            }

        }

        //BotFilter start
        if ( bungee.getBotFilter().isOnChecking( getName() ) )
        {
            disconnect( bungee.getTranslation( "already_connected_proxy" ) ); // TODO: Cache this disconnect packet
            return;
        }

        offlineId = UUID.nameUUIDFromBytes( ( "OfflinePlayer:" + getName() ).getBytes( Charsets.UTF_8 ) );

        PlayerSetUUIDEvent uuidEvent = new PlayerSetUUIDEvent( this, offlineId );
        //Because botfilter delayed a LoginEvent when player needs a check for a bot,
        //plugins can not change a uniqueId field via reflection in event, because BotFilter needs send
        //a LoginSuccess packet before a LoginEvent will be fired.
        bungee.getPluginManager().callEvent( uuidEvent );

        boolean sendLoginSuccess = ( uniqueId = uuidEvent.getUniqueId() ) != null;

        if ( uniqueId == null )
        {
            uniqueId = offlineId;
        }

        UserConnection userCon = new UserConnection( bungee, ch, getName(), InitialHandler.this );
        userCon.setCompressionThreshold( BungeeCord.getInstance().config.getCompressionThreshold() );
        //userCon.init();

        sendLoginSuccess( sendLoginSuccess );

        if ( bungee.getBotFilter().needCheck( getName(), getAddress().getAddress() ) )
        {
            sendLoginSuccess( !sendLoginSuccess ); //Send a loginSuccess if sendLoginSuccess is false
            ch.setEncoderProtocol( Protocol.GAME );
            ch.setDecoderProtocol( Protocol.BotFilter );
            ch.getHandle().pipeline().get( HandlerBoss.class ).setHandler( new Connector( userCon, bungee.getBotFilter() ) );
        } else
        {
            bungee.getLogger().log( Level.INFO, "{0} has connected", InitialHandler.this );
            finishLogin( userCon, sendLoginSuccess ); //if true, dont send again login success
        }
    }

    public void finishLogin(UserConnection userCon, boolean ignoreLoginSuccess)
    {

        Callback<LoginEvent> complete = new Callback<LoginEvent>()
        {
            @Override
            public void done(LoginEvent result, Throwable error)
            {
                if ( result.isCancelled() )
                {
                    disconnect( result.getCancelReasonComponents() );
                    return;
                }
                if ( ch.isClosed() )
                {
                    return;
                }
                if ( isInEventLoop() )
                {
                    finnalyFinishLogin( userCon, ignoreLoginSuccess );
                } else
                {
                    ch.getHandle().eventLoop().execute( () ->
                    {
                        if ( !ch.isClosing() )
                        {
                            finnalyFinishLogin( userCon, ignoreLoginSuccess );
                        }
                    } );
                }
            }
        };
        // fire login event
        bungee.getPluginManager().callEvent( new LoginEvent( InitialHandler.this, complete ) );
    }

    private void finnalyFinishLogin(UserConnection userCon, boolean ignoreLoginSuccess)
    {
        userCon.init();
        sendLoginSuccess( !ignoreLoginSuccess );
        ch.setProtocol( Protocol.GAME );

        ch.getHandle().pipeline().get( HandlerBoss.class ).setHandler( new UpstreamBridge( bungee, userCon ) ); //BotFilter

        bungee.getPluginManager().callEvent( new PostLoginEvent( userCon ) ); //BotFilter

        ServerInfo server;
        if ( bungee.getReconnectHandler() != null )
        {
            server = bungee.getReconnectHandler().getServer( userCon );
        } else
        {
            server = AbstractReconnectHandler.getForcedHost( InitialHandler.this );
        }
        if ( server == null )
        {
            server = bungee.getServerInfo( listener.getDefaultServer() );
        }
        userCon.connect( server, null, true, ServerConnectEvent.Reason.JOIN_PROXY );
        thisState = State.FINISHED;
    }

    private void sendLoginSuccess(boolean send)
    {
        if ( send )
        {
            unsafe.sendPacket( new LoginSuccess( getUniqueId().toString(), getName() ) );
        }
    }

    private boolean isInEventLoop()
    {
        return ch.getHandle().eventLoop().inEventLoop();
    }
    //BotFilter end

    @Override
    public void handle(LoginPayloadResponse response) throws Exception
    {
        disconnect( "Unexpected custom LoginPayloadResponse" );
    }

    @Override
    public void disconnect(String reason)
    {
        disconnect( TextComponent.fromLegacyText( reason ) );
    }

    @Override
    public void disconnect(final BaseComponent... reason)
    {
        if ( thisState != State.STATUS && thisState != State.PING )
        {
            ch.delayedClose( new Kick( ComponentSerializer.toString( reason ) ) );
        } else
        {
            ch.close();
        }
    }

    @Override
    public void disconnect(BaseComponent reason)
    {
        disconnect( new BaseComponent[]
        {
            reason
        } );
    }

    @Override
    public String getName()
    {
        return ( name != null ) ? name : ( loginRequest == null ) ? null : loginRequest.getData();
    }

    @Override
    public int getVersion()
    {
        return ( handshake == null ) ? -1 : handshake.getProtocolVersion();
    }

    @Override
    public InetSocketAddress getAddress()
    {
        return ch.getRemoteAddress();
    }

    @Override
    public Unsafe unsafe()
    {
        return unsafe;
    }

    @Override
    public void setOnlineMode(boolean onlineMode)
    {
        Preconditions.checkState( thisState == State.USERNAME, "Can only set online mode status whilst state is username" );
        this.onlineMode = onlineMode;
    }

    @Override
    public void setUniqueId(UUID uuid)
    {
        Preconditions.checkState( thisState == State.USERNAME, "Can only set uuid while state is username" );
        Preconditions.checkState( !onlineMode, "Can only set uuid when online mode is false" );
        this.uniqueId = uuid;
    }

    @Override
    public String getUUID()
    {
        return uniqueId.toString().replace( "-", "" );
    }

    @Override
    public String toString()
    {
        return "[" + ( ( getName() != null ) ? getName() : getAddress() ) + "] <-> InitialHandler";
    }

    @Override
    public boolean isConnected()
    {
        return !ch.isClosed();
    }
}

package net.md_5.bungee.entitymap;

import edu.umd.cs.findbugs.annotations.SuppressFBWarnings;
import io.netty.buffer.ByteBuf;
import java.util.UUID;
import net.md_5.bungee.BungeeCord;
import net.md_5.bungee.UserConnection;
import net.md_5.bungee.api.connection.ProxiedPlayer;
import net.md_5.bungee.protocol.DefinedPacket;
import net.md_5.bungee.protocol.ProtocolConstants;

class EntityMap_1_9_4 extends EntityMap {

    static final EntityMap_1_9_4 INSTANCE = new EntityMap_1_9_4();

    EntityMap_1_9_4() {
        addRewrite(0x00, ProtocolConstants.Direction.TO_CLIENT, true); // Spawn Object : PacketPlayOutSpawnEntity
        addRewrite(0x01, ProtocolConstants.Direction.TO_CLIENT, true); // Spawn Experience Orb : PacketPlayOutSpawnEntityExperienceOrb
        addRewrite(0x03, ProtocolConstants.Direction.TO_CLIENT, true); // Spawn Mob : PacketPlayOutSpawnEntityLiving
        addRewrite(0x04, ProtocolConstants.Direction.TO_CLIENT, true); // Spawn Painting : PacketPlayOutSpawnEntityPainting
        addRewrite(0x05, ProtocolConstants.Direction.TO_CLIENT, true); // Spawn Player : PacketPlayOutNamedEntitySpawn
        addRewrite(0x06, ProtocolConstants.Direction.TO_CLIENT, true); // Animation : PacketPlayOutAnimation
        addRewrite(0x08, ProtocolConstants.Direction.TO_CLIENT, true); // Block Break Animation : PacketPlayOutBlockBreakAnimation
        addRewrite(0x1B, ProtocolConstants.Direction.TO_CLIENT, false); // Entity Status : PacketPlayOutEntityStatus
        addRewrite(0x25, ProtocolConstants.Direction.TO_CLIENT, true); // Entity Relative Move : PacketPlayOutRelEntityMove
        addRewrite(0x26, ProtocolConstants.Direction.TO_CLIENT, true); // Entity Look and Relative Move : PacketPlayOutRelEntityMoveLook
        addRewrite(0x27, ProtocolConstants.Direction.TO_CLIENT, true); // Entity Look : PacketPlayOutEntityLook
        addRewrite(0x28, ProtocolConstants.Direction.TO_CLIENT, true); // Entity : PacketPlayOutEntity
        addRewrite(0x2F, ProtocolConstants.Direction.TO_CLIENT, true); // Use bed : PacketPlayOutBed
        addRewrite(0x31, ProtocolConstants.Direction.TO_CLIENT, true); // Remove Entity Effect : PacketPlayOutRemoveEntityEffect
        addRewrite(0x34, ProtocolConstants.Direction.TO_CLIENT, true); // Entity Head Look : PacketPlayOutEntityHeadRotation
        addRewrite(0x36, ProtocolConstants.Direction.TO_CLIENT, true); // Camera : PacketPlayOutCamera
        addRewrite(0x39, ProtocolConstants.Direction.TO_CLIENT, true); // Entity Metadata : PacketPlayOutEntityMetadata
        addRewrite(0x3A, ProtocolConstants.Direction.TO_CLIENT, false); // Attach Entity : PacketPlayOutAttachEntity
        addRewrite(0x3B, ProtocolConstants.Direction.TO_CLIENT, true); // Entity Velocity : PacketPlayOutEntityVelocity
        addRewrite(0x3C, ProtocolConstants.Direction.TO_CLIENT, true); // Entity Equipment : PacketPlayOutEntityEquipment
        addRewrite(0x40, ProtocolConstants.Direction.TO_CLIENT, true); // Attach Entity : PacketPlayOutMount
        addRewrite(0x48, ProtocolConstants.Direction.TO_CLIENT, true); // Collect Item : PacketPlayOutCollect
        addRewrite(0x49, ProtocolConstants.Direction.TO_CLIENT, true); // Entity Teleport : PacketPlayOutEntityTeleport
        addRewrite(0x4A, ProtocolConstants.Direction.TO_CLIENT, true); // Entity Properties : PacketPlayOutUpdateAttributes
        addRewrite(0x4B, ProtocolConstants.Direction.TO_CLIENT, true); // Entity Effect : PacketPlayOutEntityEffect

        addRewrite(0x0A, ProtocolConstants.Direction.TO_SERVER, true); // Use Entity : PacketPlayInUseEntity
        addRewrite(0x14, ProtocolConstants.Direction.TO_SERVER, true); // Entity Action : PacketPlayInEntityAction
    }

    @Override
    @SuppressFBWarnings("DLS_DEAD_LOCAL_STORE")
    public void rewriteClientbound(ByteBuf packet, int oldId, int newId) {
        super.rewriteClientbound(packet, oldId, newId);

        // Special cases
        int readerIndex = packet.readerIndex();
        int packetId = DefinedPacket.readVarInt(packet);
        int packetIdLength = packet.readerIndex() - readerIndex;
        int jumpIndex = packet.readerIndex();
        switch (packetId) {
            case 0x3A /* Attach Entity : PacketPlayOutAttachEntity */:
                rewriteInt(packet, oldId, newId, readerIndex + packetIdLength + 4);
                break;
            case 0x48 /* Collect Item : PacketPlayOutCollect */:
                DefinedPacket.readVarInt(packet);
                rewriteVarInt(packet, oldId, newId, packet.readerIndex());
                break;
            case 0x40 /* Attach Entity : PacketPlayOutMount */:
                DefinedPacket.readVarInt(packet);
                jumpIndex = packet.readerIndex();
            // Fall through on purpose to int array of IDs
            case 0x30 /* Destroy Entities : PacketPlayOutEntityDestroy */:
                int count = DefinedPacket.readVarInt(packet);
                int[] ids = new int[count];
                for (int i = 0; i < count; i++) {
                    ids[i] = DefinedPacket.readVarInt(packet);
                }
                packet.readerIndex(jumpIndex);
                packet.writerIndex(jumpIndex);
                DefinedPacket.writeVarInt(count, packet);
                for (int id : ids) {
                    if (id == oldId) {
                        id = newId;
                    } else if (id == newId) {
                        id = oldId;
                    }
                    DefinedPacket.writeVarInt(id, packet);
                }
                break;
            case 0x00 /* Spawn Object : PacketPlayOutSpawnEntity */:
                DefinedPacket.readVarInt(packet);
                DefinedPacket.readUUID(packet);
                int type = packet.readUnsignedByte();

                if (type == 60 || type == 90 || type == 91) {
                    if (type == 60 || type == 91) {
                        oldId = oldId + 1;
                        newId = newId + 1;
                    }

                    packet.skipBytes(26); // double, double, double, byte, byte
                    int position = packet.readerIndex();
                    int readId = packet.readInt();
                    if (readId == oldId) {
                        packet.setInt(position, newId);
                    } else if (readId == newId) {
                        packet.setInt(position, oldId);
                    }
                }
                break;
            case 0x05 /* Spawn Player : PacketPlayOutNamedEntitySpawn */:
                DefinedPacket.readVarInt(packet); // Entity ID
                int idLength = packet.readerIndex() - readerIndex - packetIdLength;
                UUID uuid = DefinedPacket.readUUID(packet);
                ProxiedPlayer player;
                if ((player = BungeeCord.getInstance().getPlayerByOfflineUUID(uuid)) != null) {
                    int previous = packet.writerIndex();
                    packet.readerIndex(readerIndex);
                    packet.writerIndex(readerIndex + packetIdLength + idLength);
                    DefinedPacket.writeUUID(player.getUniqueId(), packet);
                    packet.writerIndex(previous);
                }
                break;
            case 0x2C /* Combat Event : PacketPlayOutCombatEvent */:
                int event = packet.readUnsignedByte();
                if (event == 1 /* End Combat*/) {
                    DefinedPacket.readVarInt(packet);
                    rewriteInt(packet, oldId, newId, packet.readerIndex());
                } else if (event == 2 /* Entity Dead */) {
                    int position = packet.readerIndex();
                    rewriteVarInt(packet, oldId, newId, packet.readerIndex());
                    packet.readerIndex(position);
                    DefinedPacket.readVarInt(packet);
                    rewriteInt(packet, oldId, newId, packet.readerIndex());
                }
                break;
            case 0x39 /* EntityMetadata : PacketPlayOutEntityMetadata */:
                DefinedPacket.readVarInt(packet); // Entity ID
                rewriteMetaVarInt(packet, oldId + 1, newId + 1, 5); // fishing hook
                break;
        }
        packet.readerIndex(readerIndex);
    }

    @Override
    public void rewriteServerbound(ByteBuf packet, int oldId, int newId) {
        super.rewriteServerbound(packet, oldId, newId);
        // Special cases
        int readerIndex = packet.readerIndex();
        int packetId = DefinedPacket.readVarInt(packet);
        int packetIdLength = packet.readerIndex() - readerIndex;

        if (packetId == 0x1B /* Spectate : PacketPlayInSpectate */ && !BungeeCord.getInstance().getConfig().isIpForward()) {
            UUID uuid = DefinedPacket.readUUID(packet);
            ProxiedPlayer player;
            if ((player = BungeeCord.getInstance().getPlayer(uuid)) != null) {
                int previous = packet.writerIndex();
                packet.readerIndex(readerIndex);
                packet.writerIndex(readerIndex + packetIdLength);
                DefinedPacket.writeUUID(((UserConnection) player).getPendingConnection().getOfflineId(), packet);
                packet.writerIndex(previous);
            }
        }
